  '2fa.tech4': [ '— نقل السر من الخادم إلى جهازك بشكل آمن', '— transfert sécurisé du secret du serveur vers votre appareil', '— secure transfer of the secret from server to your device', 'QR secrets — نقل السر بشكل مأمن' ],
