  'a.withdraw2': [ 'كاش وجه لوجه عن طريق أحد الأدمنز.', 'Espèces en face à face via l\'un des admins.', 'Face-to-face cash via one of the admins.', 'كاش يد ليد عن طريق أدمن.' ],
  'a.withdraw3': [ 'عملات رقمية.', 'Cryptomonnaies.', 'Cryptocurrency.', 'عملات رقمية (USDT).' ],
  'a.withdrawP': [ 'يمكن للاعب سحب أرباحه مقابل مال حقيقي بإحدى الطرق الثلاث، والاختيار للاعب حسب رغبته:', 'Le joueur peut retirer ses gains en argent réel par l\'une des trois méthodes, au choix du joueur :', 'Players can withdraw their winnings as real money using one of three methods, at the player\'s choice:', 'يقدر اللعاب يسحب أرباحو مقابل فلوس حقيقية بواحدة من هاد 3 ديال الطرق، والاختيار كيبقى ليه:' ],
